query.transform:
store.rows = store.rows or {}
if type(rs) == "string" then
  local k, v = rs:match("^(%w+)=(.*)$")
  table.insert(store.rows, { key = k, value = v })
else
  vim.list_extend(store.rows, rs) -- the emitted table
end
return { columns = { "key", "value" }, rows = vim.tbl_map(function(r)
  return { r.key, r.value }
end, store.rows) }
